const updateTaskEdgeResolution = `-- name: UpdateTaskEdgeResolution :exec
UPDATE task_edges
SET resolution = $2, resolved_at = now()
WHERE id = $1 AND resolution = 'pending'
`

type UpdateTaskEdgeResolutionParams struct {
	ID         uuid.UUID      `db:"id" json:"id"`
	Resolution EdgeResolution `db:"resolution" json:"resolution"`
}

// Idempotent: only pending edges resolve, so a concurrent (serialized) writer
// can never overwrite an existing resolution.
func (q *Queries) UpdateTaskEdgeResolution(ctx context.Context, arg UpdateTaskEdgeResolutionParams) error {
	_, err := q.db.ExecContext(ctx, updateTaskEdgeResolution, arg.ID, arg.Resolution)
	return err
}

const updateTaskNodeRun = `-- name: UpdateTaskNodeRun :one
UPDATE task_nodes
SET status = $2,
    input = $3,
    output = $4,
    error = $5,
    attempt_count = $6,
    max_attempts = $7,
    next_retry_at = $8,
    wait_key = $9,
    wait_expires_at = $10,
    completed_at = $11,
    reserved_for_agent_id = $12,
    version = version + 1,
    updated_at = now()
WHERE id = $1 AND version = $13
RETURNING version
`

type UpdateTaskNodeRunParams struct {
	ID                 uuid.UUID       `db:"id" json:"id"`
	Status             TaskNodeStatus  `db:"status" json:"status"`
	Input              json.RawMessage `db:"input" json:"input"`
	Output             json.RawMessage `db:"output" json:"output"`
	Error              json.RawMessage `db:"error" json:"error"`
	AttemptCount       int32           `db:"attempt_count" json:"attempt_count"`
	MaxAttempts        int32           `db:"max_attempts" json:"max_attempts"`
	NextRetryAt        sql.NullTime    `db:"next_retry_at" json:"next_retry_at"`
	WaitKey            string          `db:"wait_key" json:"wait_key"`
	WaitExpiresAt      sql.NullTime    `db:"wait_expires_at" json:"wait_expires_at"`
	CompletedAt        sql.NullTime    `db:"completed_at" json:"completed_at"`
	ReservedForAgentID uuid.NullUUID   `db:"reserved_for_agent_id" json:"reserved_for_agent_id"`
	Version            int32           `db:"version" json:"version"`
}

// Optimistic full-state write of one run node; the WHERE clause pins the
// version the caller loaded. No affected row means a concurrent state change.
func (q *Queries) UpdateTaskNodeRun(ctx context.Context, arg UpdateTaskNodeRunParams) (int32, error) {
	row := q.db.QueryRowContext(ctx, updateTaskNodeRun,
		arg.ID,
		arg.Status,
		arg.Input,
		arg.Output,
		arg.Error,
		arg.AttemptCount,
		arg.MaxAttempts,
		arg.NextRetryAt,
		arg.WaitKey,
		arg.WaitExpiresAt,
		arg.CompletedAt,
		arg.ReservedForAgentID,
		arg.Version,
	)
	var version int32
	err := row.Scan(&version)
	return version, err
}

